def fix_version_attributes(scf_file, output_dir, file_name_prefix):
    fixed_delta = NamedTemporaryFile(prefix='%s-fixed' % file_name_prefix, suffix='.xml', dir=output_dir, delete=False)
    fixed_delta.close()
    ta5g_scfc().change_version_value_in_scf_based_on_adaptationversions_file_from_enb(scf_file.name, fixed_delta.name)
    return fixed_delta


def restore_params_changed_by_delta(result, initial_moc, delta_moc):
    initial_params = get_params(initial_moc)  # noqa: F405
    delta_params = get_params(delta_moc)  # noqa: F405

    params_to_restore = []

    for name, param in get_changed_params(initial_params, delta_params):  # noqa: F405
        params_to_restore.append(initial_params[name])

    for param in get_added_params(initial_params, delta_params):  # noqa: F405
        params_to_restore.append(get_empty_clone(param))  # noqa: F405

    if params_to_restore:
        result.update(initial_moc, params_to_restore)


def restore_changed_params_to_initial_state(result, initial_moc, current_moc):
    initial_params = get_params(initial_moc)  # noqa: F405
    current_params = get_params(current_moc)  # noqa: F405

    params_to_restore = []

    for name, param in get_changed_params(initial_params, current_params):  # noqa: F405
        params_to_restore.append(initial_params[name])

    for name, param in get_deleted_params(initial_params, current_params):  # noqa: F405
        params_to_restore.append(initial_params[name])

    for param in get_added_params(initial_params, current_params):  # noqa: F405
        params_to_restore.append(get_empty_clone(param))  # noqa: F405

    if params_to_restore:
        result.update(initial_moc, params_to_restore)


def update_params_changed_by_delta(result, initial_moc, delta_moc):
    initial_params = get_params(initial_moc)  # noqa: F405
    delta_params = get_params(delta_moc)  # noqa: F405

    params_to_add = []
    params_to_remove = []

    for param in get_added_params(initial_params, delta_params):  # noqa: F405
        params_to_add.append(param)

    for name, param in get_changed_params(delta_params, initial_params):  # noqa: F405
        params_to_remove.append(param)
        if delta_params[name].text:
            params_to_add.append(delta_params[name])

    result.add_params_to_moc(initial_moc, params_to_add)
    result.remove_params_from_moc(initial_moc, params_to_remove)


def _check_distname_in_mock(distname, initial_mocs, msg):
    if distname in initial_mocs:
        raise IncorrectOperationTypeError(msg + '({}).'.format(distname))  # noqa: F405


def _check_distname_not_in_mock(distname, initial_mocs, msg):
    if distname not in initial_mocs:
        raise IncorrectOperationTypeError(msg + '({}).'.format(distname))  # noqa: F405


def build_rollback_delta(initial_scf_path, delta_scf_path):
    ET.register_namespace('', NAMESPACE)  # noqa: F405

    logger.info(delta_scf_path)  # noqa: F405

    initial_mocs, delta_mocs = get_mocs(initial_scf_path), get_mocs(delta_scf_path)  # noqa: F405
    result = Delta()

    for distname, moc in list(delta_mocs.items()):
        operation = moc.get('operation')

        logger.info(distname)  # noqa: F405
        logger.info(operation)  # noqa: F405

        if operation == 'create':
            _check_distname_in_mock(distname, initial_mocs, 'Delta creates an object that already exists ')
            result.delete(moc)

        elif operation == 'delete':
            _check_distname_not_in_mock(distname, initial_mocs, 'Delta deletes a non-existent object ')
            result.create(initial_mocs[distname])

        elif operation == 'update':
            _check_distname_not_in_mock(distname, initial_mocs, 'Delta updates a non-existent object ')
            restore_params_changed_by_delta(result, initial_mocs[distname], moc)

        else:
            raise RuntimeError('Unknown operation %s.' % operation)

    return result


def build_scfc_using_delta(initial_scf_path, delta_scf_path):
    ET.register_namespace('', NAMESPACE)  # noqa: F405
    initial_mocs, delta_mocs = get_mocs(initial_scf_path), get_mocs(delta_scf_path)  # noqa: F405
    result = Scfc(list(initial_mocs.values()))

    for distname, moc in list(delta_mocs.items()):
        operation = moc.get('operation')

        if operation == 'create':
            _check_distname_in_mock(distname, initial_mocs, 'Delta creates an object that already exists ')
            result.create(moc)

        elif operation == 'delete':
            _check_distname_not_in_mock(distname, initial_mocs, 'Delta deletes a non-existent object ')
            result.delete(initial_mocs[distname])

        elif operation == 'update':
            _check_distname_not_in_mock(distname, initial_mocs, 'Delta updates a non-existent object ')
            update_params_changed_by_delta(result, initial_mocs[distname], moc)

        else:
            raise RuntimeError('Unknown operation %s.' % operation)

    return result


def build_rollback_to_initial_state_delta(initial_scfc_path, current_scfc_path):
    ET.register_namespace('', NAMESPACE)  # noqa: F405

    result = Delta()
    initial_mocs, current_mocs = get_mocs(initial_scfc_path), get_mocs(current_scfc_path)  # noqa: F405

    created_mocs = dict([moc for moc in list(current_mocs.items()) if moc[0] not in initial_mocs])
    deleted_mocs = dict([moc for moc in list(initial_mocs.items()) if moc[0] not in current_mocs])
    updated_mocs = dict([moc for moc in list(current_mocs.items()) if moc[0] in initial_mocs])

    for distname, moc in list(created_mocs.items()):
        result.delete(moc)

    for distname, moc in list(deleted_mocs.items()):
        result.create(initial_mocs[distname])

    for distname, moc in list(updated_mocs.items()):
        restore_changed_params_to_initial_state(result, initial_mocs[distname], moc)

    return result


def roll_back_to_initial_state(initial_scf_filename, current_scf_filename, output_dir):
    initial_scf_path = get_full_scf_path(initial_scf_filename)  # noqa: F405
    current_scf_path = get_full_scf_path(current_scf_filename)  # noqa: F405

    delta = build_rollback_to_initial_state_delta(initial_scf_path, current_scf_path)

    with NamedTemporaryFile(prefix='rollback_to_initial_state', suffix='.xml', dir=output_dir, delete=False) as output:
        delta.write(output)

    fixed_delta = fix_version_attributes(output, output_dir, file_name_prefix='rollback_to_initial_state')

    ta5g_commissioning().send_delta_commissioning(input_filepath=fixed_delta.name)


def roll_delta_back(initial_scf_filename, delta_scf_filename, output_dir, delta_directory=None):
    initial_scf_path = get_full_scf_path(initial_scf_filename)  # noqa: F405
    if not delta_directory:
        delta_scf_path = get_delta_scf_path(delta_scf_filename)  # noqa: F405
    else:
        delta_scf_path = os.path.join(delta_directory, delta_scf_filename)  # noqa: F405
    logger.console(delta_scf_path)  # noqa: F405
    factory = ReaderWriterFactory()

    delta, ext_deta = factory.create_reader(delta_scf_path)
    full, ext_full = factory.create_reader(initial_scf_path)

    rev_dict = create_reverse_dicts(delta, full)

    roll_back_delta = factory.create_writer(delta_scf_path, rev_dict, ext_deta, output_dir)

    ta5g_commissioning().send_delta_commissioning(input_filepath=roll_back_delta.name)


def roll_delta_back_aic(initial_scf_filename, delta_scf_filename):
    initial_scf_path = get_full_scf_path(initial_scf_filename)  # noqa: F405
    delta_scf_path = ta5g_commissioning().get_commissioning_file_for_enb_release_name(delta_scf_filename)
    output_directory = ta5g_interface_tools().get_robot_output_dir()
    revert_delta = os.path.join(output_directory, "revert_delta.json")  # noqa: F405
    with open(revert_delta, "w") as json_delta:
        json.dump(create_reverted_delta_aic(delta_scf_path, initial_scf_path), json_delta, indent=2)
    ta5g_commissioning().upload_and_activate_delta_aic(scfc_filename=revert_delta)


def create_reverted_delta_aic(delta_path, scf_path):  # noqa: C901
    with open(delta_path) as delta:
        orginal_delta = json.load(delta)
        revert_delta = orginal_delta[:]
    for dist_name in revert_delta:
        if dist_name['operation'] == 'add':
            dist_name['operation'] = 'remove'
        elif dist_name['operation'] == 'remove':
            dist_name['operation'] = 'add'
        elif dist_name['operation'] == 'replace':
            for parameter in dist_name['parameters']:
                if parameter['operation_type'] == 'add':
                    parameter['operation_type'] = 'remove'
                if parameter['operation_type'] == 'replace':
                    if not isinstance(parameter['value'], list):
                        parameter_to_check = (parameter['parameter_path']).strip('/')
                        value = check_parameter_initial_value_aic(scf_path, dist_name['distName'], parameter_to_check)
                        parameter['value'] = value
    return revert_delta


def check_parameter_initial_value_aic(scf_path, distName_to_check, parameter_to_check, list_param=False):  # noqa: C901
    scf = ET.parse(scf_path)
    root = scf.getroot()
    for raml in root:
        for managedObject in raml.findall('{raml21.xsd}managedObject'):
            if managedObject.get('distName') == distName_to_check:
                if list_param:
                    for list_parameter in managedObject.findall('{raml21.xsd}list'):
                        if list_parameter.attrib['name'] == parameter_to_check:
                            return parameter.text  # noqa: F405
                else:
                    for parameter in managedObject.findall('{raml21.xsd}p'):
                        if parameter.attrib['name'] == parameter_to_check:
                            return parameter.text


def build_full_scf_using_delta(full_scf_filename, delta_scf_filename, output_dir):
    full_scf_path = get_full_scf_path(full_scf_filename)  # noqa: F405
    delta_scf_path = get_full_scf_path(delta_scf_filename)  # noqa: F405

    built_scfc = build_scfc_using_delta(full_scf_path, delta_scf_path)

    with NamedTemporaryFile(prefix='built_scf', suffix='.xml', dir=output_dir, delete=False) as output:
        built_scfc.write(output)

    fixed_scfc = fix_version_attributes(output, output_dir, file_name_prefix='built_scf')
    return fixed_scfc.name
